REACT=[(0,1,Chem.BondType.DOUBLE),(1,2,Chem.BondType.SINGLE),(2,3,Chem.BondType.SINGLE),(3,4,Chem.BondType.DOUBLE),(4,0,Chem.BondType.SINGLE),(5,6,Chem.BondType.DOUBLE),(6,7,Chem.BondType.SINGLE),(7,8,Chem.BondType.TRIPLE)]+HB
PROD=[(0,4,Chem.BondType.DOUBLE),(0,1,Chem.BondType.SINGLE),(1,2,Chem.BondType.SINGLE),(2,3,Chem.BondType.SINGLE),(3,4,Chem.BondType.SINGLE),(1,5,Chem.BondType.SINGLE),(5,6,Chem.BondType.SINGLE),(6,3,Chem.BondType.SINGLE),(6,7,Chem.BondType.SINGLE),(7,8,Chem.BondType.TRIPLE)]+HB
def read(p):
    L=open(p).read().splitlines(); n=int(L[0]); return [l.split()[0] for l in L[2:2+n]],[[float(x) for x in l.split()[1:4]] for l in L[2:2+n]]
def mk(els,xyz,bonds):
    rw=Chem.RWMol()
    for e in els: rw.AddAtom(Chem.Atom(e))
    for i,j,bt in bonds: rw.AddBond(i,j,bt)
    m=rw.GetMol()
    for a in m.GetAtoms(): a.SetNoImplicit(True)
    cf=Chem.Conformer(18)
    for i,(x,y,z) in enumerate(xyz): cf.SetAtomPosition(i,(x,y,z))
    m.AddConformer(cf); Chem.SanitizeMol(m); return m
def mind(xyz):
    Cp=list(range(0,5))+list(range(9,15)); AN=list(range(5,9))+list(range(15,18))
    return min(np.linalg.norm(np.array(xyz[i])-np.array(xyz[j])) for i in Cp for j in AN)
def ang(xyz,a,b,c):
    v1=np.array(xyz[a])-np.array(xyz[b]); v2=np.array(xyz[c])-np.array(xyz[b])
    return np.degrees(np.arccos(np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))
