    cnC=[b.GetBeginAtomIdx() if isC(b.GetBeginAtomIdx()) else b.GetEndAtomIdx() for b in m.GetBonds() if b.GetBondType()==Chem.BondType.TRIPLE][0]
    Cs=[i for i in allring if isC(i)]; bh=[i for i in Cs if len([n for n in nb(i) if n in allring])==3]
    oneC=[i for i in Cs if i not in bh and set(n for n in nb(i) if n in allring)==set(bh)][0]
    bearing=[n for n in nb(cnC) if n in allring][0]; part=[n for n in nb(bearing) if n in allring and n not in bh][0]
    Q=np.array([P[i] for i in [*bh,bearing,part]]); cc=Q.mean(0); nv=np.linalg.svd(Q-cc)[2][2]
    sd=lambda i: float(np.dot(P[i]-cc,nv)); Chem.AssignStereochemistry(m,cleanIt=True,force=True)
    cip=[a.GetProp('_CIPCode') for a in m.GetAtoms() if a.GetChiralTag()!=Chem.ChiralType.CHI_UNSPECIFIED]
    return ("EXO" if sd(oneC)*sd(cnC)>0 else "ENDO"),cip
for tag in ["endo","exo"]:
    els,xyz=read(f"${base}/ts_prep/idpp_{tag}/img_06.xyz")
    d26=np.linalg.norm(np.array(xyz[5])-np.array(xyz[1])); d47=np.linalg.norm(np.array(xyz[6])-np.array(xyz[3]))
    m=mk(els,xyz,REACT); mp=AllChem.MMFFGetMoleculeProperties(m); ff=AllChem.MMFFGetMoleculeForceField(m,mp)
    ff.AddDistanceConstraint(1,5,d26-0.03,d26+0.03,20000.0); ff.AddDistanceConstraint(3,6,d47-0.03,d47+0.03,20000.0)
    ff.Minimize(maxIts=20000)
    c=m.GetConformer(); nx=[[c.GetAtomPosition(i).x,c.GetAtomPosition(i).y,c.GetAtomPosition(i).z] for i in range(18)]
    n26=np.linalg.norm(np.array(nx[5])-np.array(nx[1])); n47=np.linalg.norm(np.array(nx[6])-np.array(nx[3]))
    fam,cip=family(els,nx)
